const WEEK_1 = { day: new Date("2026-10-19"), sets: [{ weight: 40, reps: 10 }, { weight: 50, reps: 8 }] };
const WEEK_2 = { day: new Date("2026-10-26"), sets: [{ weight: 40, reps: 10 }, { weight: 55, reps: 8 }] };
